    def forecast(self, dt=5.0):
        """Run copies to the end of the shift: as is, and with every what-if undone."""
        end = M.SHIFT_HOURS * 3600

        def run(mine):
            while mine.t + dt < end and mine.shift == self.shift:
                mine.step(dt)
            return mine.totals()

